						? NormalizeSyntaxType(typeSymbol.ToDisplayString(FullyQualifiedWithNullability))
						: NormalizeSyntaxType(p.Type.ToString());
				}
				else
				{
					typeName = "object";
				}

				return prefix + typeName;
			})
			.ToArray();
		return $"{name}({string.Join(",", paramParts)})";
